import sys

def main():
    s = sys.stdin.readline().rstrip('\n')
    s = s.strip()
    n = 0
    for _ in s:
        n += 1
    flag = True
    for i in range(n // 2):
        if s[i] != s[n - 1 - i]:
            flag = False
            break
    if flag:
        print("Palindrome")
    else:
        print("Not Palindrome")

if __name__ == "__main__":
    main()
